/**
 * Keeps copied audiobooks out of Android's cloud backup and device transfer.
 *
 * A checked-out book is a copy of a file that still lives on the USB drive, so
 * backing it up would upload gigabytes that can be restored by plugging the
 * drive back in. The same goes for in-progress copies and cover thumbnails,
 * which are regenerated by a scan.
 *
 * Android needs this declared two ways: `fullBackupContent` for API 30 and
 * below, `dataExtractionRules` for API 31 and above.
 */

const { withAndroidManifest, withDangerousMod } = require('expo/config-plugins');
const fs = require('node:fs');
const path = require('node:path');

/** Paths under the app's internal files directory, i.e. `Paths.document`. */
const EXCLUDED_PATHS = ['books/', 'books-tmp/', 'covers/'];

const BACKUP_RULES_RES = 'dueback_backup_rules';
const DATA_EXTRACTION_RES = 'dueback_data_extraction_rules';

function excludeTags(indent) {
  return EXCLUDED_PATHS.map((p) => `${indent}<exclude domain="file" path="${p}" />`).join('\n');
}

function fullBackupContentXml() {
  return `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by plugins/withBackupExclusion.js — do not edit by hand. -->
<full-backup-content>
${excludeTags('    ')}
</full-backup-content>
`;
}

function dataExtractionRulesXml() {
  return `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by plugins/withBackupExclusion.js — do not edit by hand. -->
<data-extraction-rules>
    <cloud-backup>
${excludeTags('        ')}
    </cloud-backup>
    <device-transfer>
${excludeTags('        ')}
    </device-transfer>
</data-extraction-rules>
`;
}

/** @type {import('expo/config-plugins').ConfigPlugin} */
const withBackupExclusion = (config) => {
  config = withAndroidManifest(config, (cfg) => {
    const application = cfg.modResults.manifest.application?.[0];
    if (application) {
      application.$['android:fullBackupContent'] = `@xml/${BACKUP_RULES_RES}`;
      application.$['android:dataExtractionRules'] = `@xml/${DATA_EXTRACTION_RES}`;
    }
    return cfg;
  });

  config = withDangerousMod(config, [
    'android',
    async (cfg) => {
      const xmlDir = path.join(
        cfg.modRequest.platformProjectRoot,
        'app',
        'src',
        'main',
        'res',
        'xml',
      );
      fs.mkdirSync(xmlDir, { recursive: true });
      fs.writeFileSync(
        path.join(xmlDir, `${BACKUP_RULES_RES}.xml`),
        fullBackupContentXml(),
        'utf8',
      );
      fs.writeFileSync(
        path.join(xmlDir, `${DATA_EXTRACTION_RES}.xml`),
        dataExtractionRulesXml(),
        'utf8',
      );
      return cfg;
    },
  ]);

  return config;
};

module.exports = withBackupExclusion;
module.exports.EXCLUDED_PATHS = EXCLUDED_PATHS;
